#include <SoftwareSerial.h>

SoftwareSerial bluetooth(10, 11); // RX, TX

void setup() {
  Serial.begin(9600);    // USB Serial to computer
  bluetooth.begin(9600); // Wireless UART to Bluetooth
  Serial.println("--- Telemetry Bridge Active ---");
}

void loop() {
  if (bluetooth.available()) {
    Serial.write(bluetooth.read()); // Phone -> Computer
  }
  if (Serial.available()) {
    bluetooth.write(Serial.read()); // Computer -> Phone
  }
}
